/**
 * Jinx Summoner + Zombuul: rules tests.
 *
 * Wiki: https://wiki.bloodontheclocktower.com/Summoner
 * Wiki: https://wiki.bloodontheclocktower.com/Zombuul
 * (the wiki has no jinx page; each character's page lists the jinx under "Related Jinxes")
 *
 * Generated by `npm run scaffold:rules-tests`, then filled in (L118). Each test quotes the
 * jinx as the wiki words it, word for word, in a `// Wiki: "..."` comment (Trevor, 2026-11-01).
 */
import { describe, expect, it } from 'vitest';
import { findJinx, jinxesAmong } from '#lib/core/data/index.ts';
import { committedGameData, committedCharacters } from '#lib/core/testing/committed-data.ts';
import type { ReminderLabel } from '#lib/core/data/index.ts';
import { changeableSeats } from '#lib/core/rules/becomes.ts';
import { aliveForEnd, livesWhileDead } from '#lib/core/rules/game-end-helpers.ts';
import { jinxRulesBetween } from '#lib/core/rules/jinxes.ts';
import { scenario } from '#lib/core/testing/scenario.ts';
import { scriptOf } from './summoner.test-support.ts';

describe('Summoner + Zombuul jinx', () => {
	const data = committedGameData();
	const jinx = findJinx(data.jinxes, 'summoner', 'zombuul');

	it('is in jinxes.json between two official characters', () => {
		expect(data.byId.get('summoner')?.name).toBe('Summoner');
		expect(data.byId.get('zombuul')?.name).toBe('Zombuul');
		expect(jinx).toBeDefined();
		expect(jinx?.reason).not.toBe('');
	});

	it('applies only when both characters are on the script', () => {
		expect(jinxesAmong(data.jinxes, ['summoner', 'zombuul'])).toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['summoner'])).not.toContain(jinx);
		expect(jinxesAmong(data.jinxes, ['zombuul'])).not.toContain(jinx);
	});

	// No data: a dead player made the Zombuul is marked dead without the Zombuul's Dead token,
	// which is how the app already keeps a Zombuul that has died once (`aliveWhileDead`).
	const ids = ['summoner', 'zombuul', 'chef', 'empath', 'monk', 'saint'];
	const base = scenario(['summoner', 'chef', 'empath', 'monk', 'saint'], {
		script: scriptOf(ids)
	});
	const summoned = base.dies('monk').do((at) => ({
		type: 'AssignCharacter',
		seatId: at.seat('monk'),
		characterId: 'zombuul',
		alignment: 'evil',
		by: 'summoner'
	}));

	describe('a dead player summoned into the Zombuul has already died once', () => {
		it('needs no jinx data', () => {
			// Wiki: "If the Summoner summons a dead player into the Zombuul, the Zombuul has already "died once"."
			expect(jinxRulesBetween('summoner', 'zombuul', committedCharacters())).toBe(undefined);
		});

		it('lets the Summoner choose a dead player', () => {
			// Wiki: "If the Summoner summons a dead player into the Zombuul"
			const s = base.dies('monk');
			expect(changeableSeats(s.game, 'summoner', s.characters)).toContain(s.seat('monk'));
		});

		it('keeps the summoned Zombuul alive though marked dead, as after its first death', () => {
			// Wiki: "the Zombuul has already "died once"."
			const at = summoned.seat('monk');
			expect(livesWhileDead(summoned.game, at, summoned.characters)).toBe(true);
			expect(aliveForEnd(summoned.game, at, summoned.characters)).toBe(true);
		});

		it('ends with its next death, the Dead token', () => {
			// Wiki: "the Zombuul has already "died once"."
			const s = summoned.reminder('monk', 'zombuul', 'Dead' as ReminderLabel);
			expect(aliveForEnd(s.game, s.seat('monk'), s.characters)).toBe(false);
		});
	});
});
